/** Messages that carry a number or a name: the English pattern and its Bulgarian. */
const PATTERNS: readonly [RegExp, (match: RegExpMatchArray) => string][] = [
  [/^Request failed \((\d+)\)\.?$/, m => `Заявката не успя (${m[1]}).`],
  [/^API request failed \((\d+)\)$/, m => `Заявката не успя (${m[1]}).`],
  [/^Save failed \(HTTP (\d+)\)$/, m => `Записът не успя (HTTP ${m[1]})`],
  [/^HTTP (\d+)$/, m => `Грешка от сървъра (HTTP ${m[1]})`],
  [/^Cannot reach server at (.+)\.$/, m => `Няма връзка със сървъра на ${m[1]}.`],
  [/^Export contains (\d+) matching cases; narrow the export before retrying$/, m => `Експортът съдържа ${m[1]} случая; стеснете го и опитайте отново`],
  [/^Invalid (\w+) revision$/, () => "Записът е променен междувременно; презаредете"],
  [/^Invalid (\w+) conflict timestamp$/, () => "Записът е променен междувременно; презаредете"],
  [/^(.*) Please remove identifying information before saving\.$/, m => `${m[1]} Премахнете идентифициращата информация, преди да запишете.`],
]

/** The message in the reader's language: Bulgarian when known, otherwise as sent. */
export function localizeServerMessage(message: string, language: string | null | undefined): string {
  if (!language?.toLowerCase().startsWith("bg")) return message
  const text = message.trim()
  const exact = SERVER_MESSAGES_BG[text]
  if (exact) return exact
  for (const [pattern, render] of PATTERNS) {
    const match = text.match(pattern)
    if (match) return render(match)
  }
  return message
}
